{"source":"import json
import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string to a UTC datetime.
    Returns None if the string is missing, null, or naive (no offset)."""
    if s is None:
        return None
    s = str(s).strip()
    if not s:
        return None
    # Check if it's naive (no offset info like Z, +HH:MM, -HH:MM)
    # Naive strings have no trailing Z, +, or - after the time portion
    # A naive ISO8601 string like "2026-10-29T09:00:00" has no offset
    # An offset-aware string ends with Z, +HH:MM, or -HH:MM
    # We need to detect if there's an offset component
    # Find the last occurrence of + or - after the date part
    # Simple approach: try to parse and check if timezone info is present

    # Check for Z suffix (UTC)
    if s.endswith('Z') or s.endswith('z'):
        base = s[:-1]
        try:
            dt = datetime.fromisoformat(base)
            return dt.replace(tzinfo=timezone.utc)
        except (ValueError, TypeError):
            return None

    # Check for explicit offset like +05:30 or -03:00
    # Find the last + or - that could be an offset
    # The offset is typically the last + or - in the string after the time portion
    # Strategy: try parsing with fromisoformat and check if tzinfo is set

    try:
        dt = datetime.fromisoformat(s)
    except (ValueError, TypeError):
        return None

    # If no timezone info, it's naive - skip it
    if dt.tzinfo is None:
        return None

    # Convert to UTC
    return dt.astimezone(timezone.utc)


def format_utc(dt):
    """Format a UTC datetime as YYYY-MM-DDTHH:MM:SSZ."""
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def main():
    with open(sys.argv[1], 'r') as f:
        data = json.load(f)

    as_of_str = data.get('as_of')
    if as_of_str is None:
        print(json.dumps([]))
        return

    as_of = parse_offset_aware(as_of_str)
    if as_of is None:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    result = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        # Get due value - skip if missing, null, or naive
        due_raw = r.get('due')
        if due_raw is None:
            continue

        due_dt = parse_offset_aware(due_raw)
        if due_dt is None:
            continue

        # Check if due AT OR BEFORE as_of (comparing actual instants)
        if due_dt <= as_of:
            result.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due_dt)
            })

    # Sort by actual due instant (from due_utc string, but we need the parsed datetime)
    # Re-parse for sorting, or store the parsed datetime alongside
    # Actually, let's re-sort by parsing the due_utc back or by re-evaluating
    # Better: sort by the actual datetime, then by id

    # Re-build with parsed datetime for sorting
    result_sorted = []
    for r in reminders:
        if r.get('completed', False):
            continue
        due_raw = r.get('due')
        if due_raw is None:
            continue
        due_dt = parse_offset_aware(due_raw)
        if due_dt is None:
            continue
        if due_dt <= as_of:
            result_sorted.append((due_dt, r['id'], r['title']))

    # Sort by due instant, then by id
    result_sorted.sort(key=lambda x: (x[0], x[1]))

    output = [
        {
            'id': item[1],
            'title': item[2],
            'due_utc': format_utc(item[0])
        }
        for item in result_sorted
    ]

    print(json.dumps(output))


if __name__ == '__main__':
    main()"}

